#### Component 2: JWT Signing Service (Identity Provider)

Centralized service for signing tokens with RSA private key:

```csharp
// JwtSigningService.cs - Identity Provider Token Generation
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.IdentityModel.Tokens;

public class JwtSigningService
{
    private readonly RsaSecurityKey _signingKey;
    private readonly string _issuer;
    private readonly string _audience;
    private readonly ILogger<JwtSigningService> _logger;

    public JwtSigningService(
        RsaSecurityKey signingKey,
        string issuer,
        string audience,
        ILogger<JwtSigningService> logger)
    {
        _signingKey = signingKey;
        _issuer = issuer;
        _audience = audience;
        _logger = logger;
    }

    public string GenerateAccessToken(User user, TimeSpan lifetime)
    {
        var claims = new List<Claim>
        {
            new Claim(JwtRegisteredClaimNames.Sub, user.Id),
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
            new Claim("scope", string.Join(" ", user.Scopes)),
            new Claim("tenantId", user.TenantId),
            new Claim("purposeOfUse", "Treatment") // Or from request context
        };

        // Add roles as individual claims
        foreach (var role in user.Roles)
        {
            claims.Add(new Claim(ClaimTypes.Role, role));
        }

        // Add user-type specific claims
        if (user.UserType == UserType.Provider)
        {
            claims.Add(new Claim("npi", user.NPI));
            claims.Add(new Claim("assignedStates", string.Join(",", user.AssignedStates)));
        }
        else if (user.UserType == UserType.Member)
        {
            claims.Add(new Claim("memberId", user.MemberId));
        }

        var tokenDescriptor = new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity(claims),
            Expires = DateTime.UtcNow.Add(lifetime),
            Issuer = _issuer,
            Audience = _audience,
            SigningCredentials = new SigningCredentials(
                _signingKey,
                SecurityAlgorithms.RsaSha256
            )
        };

        var tokenHandler = new JwtSecurityTokenHandler();
        var token = tokenHandler.CreateToken(tokenDescriptor);
        var tokenString = tokenHandler.WriteToken(token);

        _logger.LogInformation(
            "Generated access token for user {UserId}, tenant {TenantId}, expires {Expiration}",
            user.Id, user.TenantId, tokenDescriptor.Expires);

        return tokenString;
    }

    public string GenerateRefreshToken(User user, TimeSpan lifetime)
    {
        // Refresh tokens: minimal claims, longer lifetime
        var claims = new List<Claim>
        {
            new Claim(JwtRegisteredClaimNames.Sub, user.Id),
            new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()),
            new Claim("token_type", "refresh"),
            new Claim("tenantId", user.TenantId)
        };

        var tokenDescriptor = new SecurityTokenDescriptor
        {
            Subject = new ClaimsIdentity(claims),
            Expires = DateTime.UtcNow.Add(lifetime), // Typically 30 days
            Issuer = _issuer,
            Audience = _issuer, // Refresh tokens only accepted by token endpoint
            SigningCredentials = new SigningCredentials(
                _signingKey,
                SecurityAlgorithms.RsaSha256
            )
        };

        var tokenHandler = new JwtSecurityTokenHandler();
        var token = tokenHandler.CreateToken(tokenDescriptor);
        return tokenHandler.WriteToken(token);
    }
}
```

