#### Component 3: JWT Validation Middleware (API Services)

Middleware for validating incoming JWT tokens in microservices:

```csharp
// JwtValidationMiddleware.cs - API Service Token Validation
using Microsoft.AspNetCore.Http;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;

public class JwtValidationMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IPublicKeyProvider _publicKeyProvider;
    private readonly ILogger<JwtValidationMiddleware> _logger;
    private readonly string _issuer;
    private readonly string _audience;

    public JwtValidationMiddleware(
        RequestDelegate next,
        IPublicKeyProvider publicKeyProvider,
        IConfiguration configuration,
        ILogger<JwtValidationMiddleware> logger)
    {
        _next = next;
        _publicKeyProvider = publicKeyProvider;
        _logger = logger;
        _issuer = configuration["Jwt:Issuer"];
        _audience = configuration["Jwt:Audience"];
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var token = ExtractTokenFromHeader(context);
        if (string.IsNullOrEmpty(token))
        {
            context.Response.StatusCode = 401;
            await context.Response.WriteAsJsonAsync(new
            {
                error = "missing_token",
                error_description = "Authorization header with Bearer token required"
            });
            return;
        }

        try
        {
            // Validate token and extract claims
            var claimsPrincipal = await ValidateTokenAsync(token);

            // Attach claims to HttpContext for downstream use
            context.User = claimsPrincipal;

            // Extract key claims for audit logging
            var userId = claimsPrincipal.FindFirst(JwtRegisteredClaimNames.Sub)?.Value;
            var tenantId = claimsPrincipal.FindFirst("tenantId")?.Value;

            _logger.LogInformation(
                "Token validated successfully for user {UserId}, tenant {TenantId}",
                userId, tenantId);

            await _next(context);
        }
        catch (SecurityTokenExpiredException)
        {
            _logger.LogWarning("Token expired for request to {Path}", context.Request.Path);
            context.Response.StatusCode = 401;
            await context.Response.WriteAsJsonAsync(new
            {
                error = "token_expired",
                error_description = "Access token has expired. Use refresh token to obtain new access token."
            });
        }
        catch (SecurityTokenInvalidSignatureException)
        {
            _logger.LogError("Invalid token signature for request to {Path}", context.Request.Path);
            context.Response.StatusCode = 401;
            await context.Response.WriteAsJsonAsync(new
            {
                error = "invalid_token",
                error_description = "Token signature validation failed"
            });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Token validation failed for request to {Path}", context.Request.Path);
            context.Response.StatusCode = 401;
            await context.Response.WriteAsJsonAsync(new
            {
                error = "invalid_token",
                error_description = "Token validation failed"
            });
        }
    }

    private string? ExtractTokenFromHeader(HttpContext context)
    {
        var authHeader = context.Request.Headers["Authorization"].ToString();
        if (string.IsNullOrEmpty(authHeader) || !authHeader.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
            return null;

        return authHeader.Substring("Bearer ".Length).Trim();
    }

    private async Task<ClaimsPrincipal> ValidateTokenAsync(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();

        // Fetch public keys from JWKS endpoint (cached)
        var signingKeys = await _publicKeyProvider.GetSigningKeysAsync();

        var validationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidIssuer = _issuer,

            ValidateAudience = true,
            ValidAudience = _audience,

            ValidateIssuerSigningKey = true,
            IssuerSigningKeys = signingKeys,

            ValidateLifetime = true,
            ClockSkew = TimeSpan.FromMinutes(2), // Allow 2 min clock skew

            RequireExpirationTime = true,
            RequireSignedTokens = true
        };

        // Validate token and return claims principal
        var principal = tokenHandler.ValidateToken(token, validationParameters, out var validatedToken);

        // Additional validation: ensure algorithm is RS256 or ES256
        if (validatedToken is JwtSecurityToken jwtToken)
        {
            if (jwtToken.Header.Alg != SecurityAlgorithms.RsaSha256 &&
                jwtToken.Header.Alg != SecurityAlgorithms.EcdsaSha256)
            {
                throw new SecurityTokenValidationException("Token must be signed with RS256 or ES256");
            }
        }

        return principal;
    }
}

// PublicKeyProvider.cs - Fetches and caches JWKS public keys
public interface IPublicKeyProvider
{
    Task<IEnumerable<SecurityKey>> GetSigningKeysAsync();
}

public class JwksPublicKeyProvider : IPublicKeyProvider
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly string _jwksUri;
    private readonly ILogger<JwksPublicKeyProvider> _logger;

    public JwksPublicKeyProvider(
        HttpClient httpClient,
        IMemoryCache cache,
        IConfiguration configuration,
        ILogger<JwksPublicKeyProvider> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _jwksUri = configuration["Jwt:JwksUri"];
        _logger = logger;
    }

    public async Task<IEnumerable<SecurityKey>> GetSigningKeysAsync()
    {
        const string cacheKey = "jwks_signing_keys";

        if (_cache.TryGetValue(cacheKey, out IEnumerable<SecurityKey> cachedKeys))
        {
            _logger.LogDebug("Returning cached JWKS signing keys");
            return cachedKeys;
        }

        _logger.LogInformation("Fetching JWKS signing keys from {JwksUri}", _jwksUri);

        var response = await _httpClient.GetStringAsync(_jwksUri);
        var jwks = new JsonWebKeySet(response);
        var keys = jwks.GetSigningKeys();

        // Cache keys for 24 hours
        _cache.Set(cacheKey, keys, TimeSpan.FromHours(24));

        _logger.LogInformation("Cached {KeyCount} JWKS signing keys", keys.Count());

        return keys;
    }
}
```

