#### Component 4: Token Refresh Flow Implementation

Client-side implementation for refresh token flow:

```typescript
// TokenManager.ts - Client-side token management with refresh
import jwtDecode from 'jwt-decode';

interface TokenResponse {
  access_token: string;
  refresh_token: string;
  expires_in: number; // seconds
  token_type: 'Bearer';
}

interface TokenClaims {
  sub: string;
  exp: number;
  iat: number;
  scope: string;
  tenantId: string;
}

export class TokenManager {
  private accessToken: string | null = null;
  private refreshToken: string | null = null;
  private refreshPromise: Promise<string> | null = null;

  constructor(
    private tokenEndpoint: string,
    private clientId: string,
    private storage: Storage = sessionStorage
  ) {
    // Load tokens from storage
    this.accessToken = storage.getItem('access_token');
    this.refreshToken = storage.getItem('refresh_token');
  }

  // Store tokens securely
  public setTokens(response: TokenResponse): void {
    this.accessToken = response.access_token;
    this.refreshToken = response.refresh_token;

    // Store in sessionStorage (cleared on tab close)
    // For persistent login, use encrypted localStorage or httpOnly cookies
    this.storage.setItem('access_token', response.access_token);
    this.storage.setItem('refresh_token', response.refresh_token);
    this.storage.setItem('expires_at',
      (Date.now() + response.expires_in * 1000).toString());
  }

  // Get valid access token (refresh if expired)
  public async getAccessToken(): Promise<string> {
    if (!this.accessToken) {
      throw new Error('No access token available. User must authenticate.');
    }

    // Check if token is expired or will expire in next 60 seconds
    if (this.isTokenExpired(this.accessToken, 60)) {
      // Token expired, need to refresh
      return await this.refreshAccessToken();
    }

    return this.accessToken;
  }

  // Check if token is expired (with buffer)
  private isTokenExpired(token: string, bufferSeconds: number = 0): boolean {
    try {
      const claims = jwtDecode<TokenClaims>(token);
      const expirationTime = claims.exp * 1000; // Convert to milliseconds
      const now = Date.now();
      return now >= (expirationTime - bufferSeconds * 1000);
    } catch (error) {
      console.error('Failed to decode token:', error);
      return true; // Treat decode errors as expired
    }
  }

  // Refresh access token using refresh token
  private async refreshAccessToken(): Promise<string> {
    // Prevent multiple simultaneous refresh calls
    if (this.refreshPromise) {
      return await this.refreshPromise;
    }

    if (!this.refreshToken) {
      throw new Error('No refresh token available. User must re-authenticate.');
    }

    this.refreshPromise = this.performTokenRefresh();

    try {
      const newAccessToken = await this.refreshPromise;
      return newAccessToken;
    } finally {
      this.refreshPromise = null;
    }
  }

  private async performTokenRefresh(): Promise<string> {
    console.log('Refreshing access token...');

    const response = await fetch(this.tokenEndpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: new URLSearchParams({
        grant_type: 'refresh_token',
        refresh_token: this.refreshToken!,
        client_id: this.clientId
      })
    });

    if (!response.ok) {
      // Refresh token invalid or expired
      this.clearTokens();
      throw new Error('Refresh token invalid. User must re-authenticate.');
    }

    const tokenResponse: TokenResponse = await response.json();
    this.setTokens(tokenResponse);

    console.log('Access token refreshed successfully');
    return tokenResponse.access_token;
  }

  // Make authenticated API call with automatic token refresh
  public async fetch(url: string, options: RequestInit = {}): Promise<Response> {
    const token = await this.getAccessToken();

    const headers = new Headers(options.headers || {});
    headers.set('Authorization', `Bearer ${token}`);

    const response = await fetch(url, {
      ...options,
      headers
    });

    // Handle 401 Unauthorized (token might have expired between check and use)
    if (response.status === 401) {
      console.log('Received 401, attempting token refresh...');

      // Try refreshing token and retrying request once
      const newToken = await this.refreshAccessToken();
      headers.set('Authorization', `Bearer ${newToken}`);

      return fetch(url, {
        ...options,
        headers
      });
    }

    return response;
  }

  // Clear tokens (logout)
  public clearTokens(): void {
    this.accessToken = null;
    this.refreshToken = null;
    this.storage.removeItem('access_token');
    this.storage.removeItem('refresh_token');
    this.storage.removeItem('expires_at');
  }
}

// Usage example
const tokenManager = new TokenManager(
  'https://auth.gainwell.com/oauth/token',
  'gainwell-provider-portal'
);

// After OAuth login
tokenManager.setTokens(oauthResponse);

// Making API calls (automatic refresh if needed)
const response = await tokenManager.fetch('https://api.gainwell.com/claims/12345');
const claim = await response.json();
```

