#### Phase 1: Identity Provider Token Generation (Weeks 1-2)

**Step 1: Generate RSA Key Pair**

```bash
# Generate RSA 2048-bit key pair (minimum for production)
openssl genrsa -out private-key.pem 2048

# Extract public key
openssl rsa -in private-key.pem -pubout -out public-key.pem

# Convert to PEM format for Azure Key Vault
openssl pkcs8 -topk8 -inform PEM -outform PEM -in private-key.pem -out private-key-pkcs8.pem -nocrypt

# Import to Azure Key Vault
az keyvault key import --vault-name "gainwell-auth-keys" --name "jwt-signing-key-2025-01" --pem-file private-key-pkcs8.pem
```

**Step 2: Implement JWT Signing Service**

```csharp
// Startup.cs - Configure JWT signing
public void ConfigureServices(IServiceCollection services)
{
    // Load private key from Azure Key Vault
    var keyVaultClient = new KeyVaultClient(...);
    var keyBundle = await keyVaultClient.GetKeyAsync("https://gainwell-auth-keys.vault.azure.net", "jwt-signing-key-2025-01");
    var rsa = keyBundle.Key.ToRSA();
    var signingKey = new RsaSecurityKey(rsa)
    {
        KeyId = "gainwell-auth-2025-01"
    };

    services.AddSingleton(signingKey);
    services.AddScoped<IJwtSigningService, JwtSigningService>();

    services.Configure<JwtOptions>(options =>
    {
        options.Issuer = "https://auth.gainwell.com";
        options.Audience = "https://api.gainwell.com";
        options.AccessTokenLifetime = TimeSpan.FromMinutes(15);
        options.RefreshTokenLifetime = TimeSpan.FromDays(30);
    });
}

// TokenController.cs - OAuth token endpoint
[Route("oauth/token")]
public class TokenController : ControllerBase
{
    private readonly IJwtSigningService _signingService;
    private readonly IUserService _userService;

    [HttpPost]
    public async Task<IActionResult> Token([FromForm] TokenRequest request)
    {
        if (request.GrantType == "authorization_code")
        {
            // Exchange authorization code for tokens
            var user = await ValidateAuthorizationCode(request.Code);
            if (user == null)
                return BadRequest(new { error = "invalid_grant" });

            var accessToken = _signingService.GenerateAccessToken(user, TimeSpan.FromMinutes(15));
            var refreshToken = _signingService.GenerateRefreshToken(user, TimeSpan.FromDays(30));

            return Ok(new TokenResponse
            {
                AccessToken = accessToken,
                TokenType = "Bearer",
                ExpiresIn = 900, // 15 minutes in seconds
                RefreshToken = refreshToken,
                Scope = string.Join(" ", user.Scopes)
            });
        }
        else if (request.GrantType == "refresh_token")
        {
            // Validate refresh token and issue new access token
            var principal = _signingService.ValidateRefreshToken(request.RefreshToken);
            if (principal == null)
                return BadRequest(new { error = "invalid_grant" });

            var userId = principal.FindFirst(JwtRegisteredClaimNames.Sub)?.Value;
            var user = await _userService.GetByIdAsync(userId);

            // Check if refresh token revoked
            var jti = principal.FindFirst(JwtRegisteredClaimNames.Jti)?.Value;
            if (await _revokedTokenRepository.IsRevokedAsync(jti))
                return BadRequest(new { error = "invalid_grant" });

            var newAccessToken = _signingService.GenerateAccessToken(user, TimeSpan.FromMinutes(15));

            return Ok(new TokenResponse
            {
                AccessToken = newAccessToken,
                TokenType = "Bearer",
                ExpiresIn = 900,
                RefreshToken = request.RefreshToken, // Optionally rotate refresh token
                Scope = string.Join(" ", user.Scopes)
            });
        }

        return BadRequest(new { error = "unsupported_grant_type" });
    }
}
```

**Step 3: Deploy JWKS Endpoint**

```csharp
// JwksController.cs - Serve public keys for token validation
[Route(".well-known")]
public class JwksController : ControllerBase
{
    private readonly IEnumerable<RsaSecurityKey> _signingKeys;

    [HttpGet("jwks.json")]
    [ResponseCache(Duration = 86400)] // Cache for 24 hours
    public IActionResult Jwks()
    {
        var keys = _signingKeys.Select(key => new
        {
            kty = "RSA",
            use = "sig",
            kid = key.KeyId,
            n = Base64UrlEncoder.Encode(key.Rsa.ExportParameters(false).Modulus),
            e = Base64UrlEncoder.Encode(key.Rsa.ExportParameters(false).Exponent),
            alg = "RS256"
        });

        return Ok(new { keys });
    }
}
```

