// Startup.cs
public void ConfigureServices(IServiceCollection services)
{
    services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
        .AddJwtBearer(options =>
        {
            options.Authority = "https://auth.gainwell.com";
            options.Audience = "https://api.gainwell.com";

            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidIssuer = "https://auth.gainwell.com",

                ValidateAudience = true,
                ValidAudience = "https://api.gainwell.com",

                ValidateLifetime = true,
                ClockSkew = TimeSpan.FromMinutes(2),

                ValidateIssuerSigningKey = true,
                // JWKS keys fetched automatically from Authority + /.well-known/openid-configuration
            };

            // Custom event handlers
            options.Events = new JwtBearerEvents
            {
                OnTokenValidated = context =>
                {
                    // Log successful authentication
                    var userId = context.Principal.FindFirst(JwtRegisteredClaimNames.Sub)?.Value;
                    var tenantId = context.Principal.FindFirst("tenantId")?.Value;

                    _logger.LogInformation("Token validated for user {UserId}, tenant {TenantId}", userId, tenantId);
                    return Task.CompletedTask;
                },

                OnAuthenticationFailed = context =>
                {
                    _logger.LogWarning("Token validation failed: {Exception}", context.Exception.Message);
                    return Task.CompletedTask;
                },

                OnChallenge = context =>
                {
                    // Customize 401 response
                    context.HandleResponse();
                    context.Response.StatusCode = 401;
                    context.Response.ContentType = "application/json";
                    return context.Response.WriteAsJsonAsync(new
                    {
                        error = "unauthorized",
                        error_description = context.ErrorDescription ?? "Invalid or missing token"
                    });
                }
            };
        });

    services.AddAuthorization(options =>
    {
        // Policy requiring specific scope
        options.AddPolicy("ClaimsRead", policy =>
            policy.RequireClaim("scope", "claims:read"));

        // Policy requiring role
        options.AddPolicy("ProviderOnly", policy =>
            policy.RequireRole("Provider"));

        // Policy combining multiple requirements
        options.AddPolicy("ClaimsWrite", policy =>
        {
            policy.RequireClaim("scope", "claims:write");
            policy.RequireAuthenticatedUser();
        });
    });
}

public void Configure(IApplicationBuilder app)
{
    app.UseAuthentication();
    app.UseAuthorization();

    app.UseEndpoints(endpoints =>
    {
        endpoints.MapControllers();
    });
}
