// auth.service.ts - Angular/React authentication service
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, BehaviorSubject } from 'rxjs';
import { tap } from 'rxjs/operators';

interface TokenResponse {
  access_token: string;
  refresh_token: string;
  expires_in: number;
  token_type: string;
}

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly TOKEN_ENDPOINT = 'https://auth.gainwell.com/oauth/token';
  private readonly AUTHORIZE_ENDPOINT = 'https://auth.gainwell.com/oauth/authorize';

  private currentUserSubject = new BehaviorSubject<any>(null);
  public currentUser$ = this.currentUserSubject.asObservable();

  constructor(private http: HttpClient) {
    // Check for existing token on init
    this.loadTokenFromStorage();
  }

  // OAuth Authorization Code Flow
  public login(redirectUri: string): void {
    const params = new URLSearchParams({
      response_type: 'code',
      client_id: 'gainwell-provider-portal',
      redirect_uri: redirectUri,
      scope: 'claims:read claims:write profile',
      state: this.generateRandomState()
    });

    // Redirect to authorization endpoint
    window.location.href = `${this.AUTHORIZE_ENDPOINT}?${params.toString()}`;
  }

  // Handle OAuth callback
  public async handleCallback(code: string, state: string): Promise<void> {
    // Validate state parameter (CSRF protection)
    const savedState = sessionStorage.getItem('oauth_state');
    if (state !== savedState) {
      throw new Error('Invalid state parameter');
    }

    // Exchange authorization code for tokens
    const tokenResponse = await this.http.post<TokenResponse>(this.TOKEN_ENDPOINT, {
      grant_type: 'authorization_code',
      code,
      client_id: 'gainwell-provider-portal',
      redirect_uri: window.location.origin + '/callback'
    }).toPromise();

    this.storeTokens(tokenResponse);
  }

  private storeTokens(response: TokenResponse): void {
    // Store in sessionStorage (cleared on tab close)
    sessionStorage.setItem('access_token', response.access_token);
    sessionStorage.setItem('refresh_token', response.refresh_token);
    sessionStorage.setItem('expires_at',
      (Date.now() + response.expires_in * 1000).toString());

    // Decode token to get user info
    const payload = this.decodeToken(response.access_token);
    this.currentUserSubject.next(payload);
  }

  private loadTokenFromStorage(): void {
    const token = sessionStorage.getItem('access_token');
    if (token) {
      const payload = this.decodeToken(token);
      this.currentUserSubject.next(payload);
    }
  }

  private decodeToken(token: string): any {
    const parts = token.split('.');
    if (parts.length !== 3) {
      throw new Error('Invalid token format');
    }

    const payload = JSON.parse(atob(parts[1]));
    return payload;
  }

  private generateRandomState(): string {
    const state = Math.random().toString(36).substring(7);
    sessionStorage.setItem('oauth_state', state);
    return state;
  }

  public logout(): void {
    sessionStorage.removeItem('access_token');
    sessionStorage.removeItem('refresh_token');
    sessionStorage.removeItem('expires_at');
    this.currentUserSubject.next(null);
  }
}

// HTTP Interceptor for adding tokens to requests
@Injectable()
export class TokenInterceptor implements HttpInterceptor {
  constructor(private auth: AuthService) {}

  intercept(request: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    const token = sessionStorage.getItem('access_token');

    if (token) {
      request = request.clone({
        setHeaders: {
          Authorization: `Bearer ${token}`
        }
      });
    }

    return next.handle(request).pipe(
      catchError(error => {
        if (error.status === 401) {
          // Token expired, attempt refresh
          return this.handle401Error(request, next);
        }
        return throwError(error);
      })
    );
  }

