// AuthContext.tsx - React Native context for authentication
import React, { createContext, useContext, useState, useEffect } from 'react';
import * as SecureStore from 'expo-secure-store';
import jwtDecode from 'jwt-decode';

interface AuthContextType {
  accessToken: string | null;
  login: (username: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  refreshToken: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC = ({ children }) => {
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const [refreshToken, setRefreshToken] = useState<string | null>(null);

  // Load tokens from secure storage on app start
  useEffect(() => {
    loadTokens();
  }, []);

  // Schedule token refresh before expiration
  useEffect(() => {
    if (accessToken) {
      scheduleTokenRefresh();
    }
  }, [accessToken]);

  const loadTokens = async () => {
    const storedAccessToken = await SecureStore.getItemAsync('access_token');
    const storedRefreshToken = await SecureStore.getItemAsync('refresh_token');

    if (storedAccessToken) {
      // Check if token expired
      const decoded: any = jwtDecode(storedAccessToken);
      if (decoded.exp * 1000 > Date.now()) {
        setAccessToken(storedAccessToken);
        setRefreshToken(storedRefreshToken);
      } else {
        // Token expired, try refresh
        if (storedRefreshToken) {
          await performTokenRefresh(storedRefreshToken);
        }
      }
    }
  };

  const login = async (username: string, password: string) => {
    const response = await fetch('https://auth.gainwell.com/oauth/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'password',
        username,
        password,
        client_id: 'gainwell-go-mobile'
      })
    });

    const tokens = await response.json();
    await storeTokens(tokens);
  };

  const storeTokens = async (tokens: any) => {
    // Store in encrypted secure storage (iOS Keychain / Android Keystore)
    await SecureStore.setItemAsync('access_token', tokens.access_token);
    await SecureStore.setItemAsync('refresh_token', tokens.refresh_token);

    setAccessToken(tokens.access_token);
    setRefreshToken(tokens.refresh_token);
  };

  const performTokenRefresh = async (currentRefreshToken: string) => {
    const response = await fetch('https://auth.gainwell.com/oauth/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'refresh_token',
        refresh_token: currentRefreshToken,
        client_id: 'gainwell-go-mobile'
      })
    });

    if (response.ok) {
      const tokens = await response.json();
      await storeTokens(tokens);
    } else {
      // Refresh failed, user must re-login
      await logout();
    }
  };

  const scheduleTokenRefresh = () => {
    if (!accessToken) return;

    const decoded: any = jwtDecode(accessToken);
    const expiresIn = decoded.exp * 1000 - Date.now();
    const refreshAt = expiresIn - 60000; // Refresh 1 minute before expiration

    if (refreshAt > 0) {
      setTimeout(async () => {
        if (refreshToken) {
          await performTokenRefresh(refreshToken);
        }
      }, refreshAt);
    }
  };

  const logout = async () => {
    await SecureStore.deleteItemAsync('access_token');
    await SecureStore.deleteItemAsync('refresh_token');
    setAccessToken(null);
    setRefreshToken(null);
  };

  return (
    <AuthContext.Provider value={{ accessToken, login, logout, refreshToken: () => performTokenRefresh(refreshToken!) }}>
      {children}
    </AuthContext.Provider>
  );
};

// Hook for accessing auth context
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
};

// Axios interceptor for API calls
import axios from 'axios';

const apiClient = axios.create({
  baseURL: 'https://api.gainwell.com'
});

apiClient.interceptors.request.use(async (config) => {
  const token = await SecureStore.getItemAsync('access_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export default apiClient;
