#### Best Practice 4: Cache JWKS Public Keys with 24-Hour TTL

**Guideline:** Fetch public keys from JWKS endpoint and cache for 24 hours to reduce latency and dependency on auth server.

```csharp
public class JwksPublicKeyProvider : IPublicKeyProvider
{
    private readonly IMemoryCache _cache;
    private const string CacheKey = "jwks_signing_keys";
    private const int CacheDurationHours = 24;

    public async Task<IEnumerable<SecurityKey>> GetSigningKeysAsync()
    {
        // Check cache first
        if (_cache.TryGetValue(CacheKey, out IEnumerable<SecurityKey> cachedKeys))
        {
            return cachedKeys;
        }

        // Fetch from JWKS endpoint
        var response = await _httpClient.GetStringAsync("https://auth.gainwell.com/.well-known/jwks.json");
        var jwks = new JsonWebKeySet(response);
        var keys = jwks.GetSigningKeys();

        // Cache for 24 hours
        _cache.Set(CacheKey, keys, TimeSpan.FromHours(CacheDurationHours));

        return keys;
    }
}
```

