  "patientName": "John Doe",
  "ssn": "123-45-6789",
  "diagnosis": "Type 2 Diabetes"
}

// ✅ GOOD: Only identifiers and authorization claims
{
  "sub": "user-12345",
  "memberId": "M-67890",
  "roles": ["Member"],
  "scope": "patient:read",
  "tenantId": "CA-DHCS"
}
