#### Best Practice 6: Implement Token Revocation for Refresh Tokens

**Guideline:** Maintain revocation list for refresh tokens to enable immediate logout/revocation.

```csharp
public class RefreshTokenRevocationService
{
    private readonly IDistributedCache _redis;

    public async Task RevokeTokenAsync(string jti, DateTime expiration)
    {
        var ttl = expiration - DateTime.UtcNow;
        if (ttl.TotalSeconds > 0)
        {
            // Store revoked token ID until expiration
            await _redis.SetStringAsync(
                $"revoked:{jti}",
                "revoked",
                new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = ttl });
        }
    }

    public async Task<bool> IsRevokedAsync(string jti)
    {
        var value = await _redis.GetStringAsync($"revoked:{jti}");
        return value != null;
    }
}

// Check revocation on refresh token use
