var userId = token.Claims.First(c => c.Type == "sub").Value;

// ✅ GOOD: Validating signature
var validatedToken = handler.ValidateToken(tokenString, validationParameters, out var securityToken);
var userId = validatedToken.FindFirst(JwtRegisteredClaimNames.Sub)?.Value;
